<script setup>
import { ref } from 'vue'; import { ArrowRight, Box, Eye, EyeOff, LockKeyhole, PackageSearch, ReceiptText } from 'lucide-vue-next'; import BrandMark from './BrandMark.vue'; import ThemeToggle from './ThemeToggle.vue'; import BaseButton from './ui/BaseButton.vue'; import FormField from './ui/FormField.vue'; import { request } from '../lib/http'
const props=defineProps({theme:String}); const emit=defineEmits(['update:theme','logged-in','notify']); const email=ref(''); const password=ref(''); const visible=ref(false); const loading=ref(false)
async function login(){loading.value=true;try{const data=await request('/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});emit('logged-in',data.user)}catch(e){emit('notify',e.message)}finally{loading.value=false}}
</script>
<template><div class="login"><header><BrandMark/><ThemeToggle :model-value="theme" @update:model-value="emit('update:theme',$event)"/></header><main><section class="intro"><p class="eyebrow">Haseen Telecom · Admin Portal</p><h1>Your business.<br/><em>Connected &amp; in control.</em></h1><p>Manage your catalog, track inventory and keep every sale in one place.</p><div class="tags"><span><PackageSearch :size="15"/>Catalog</span><span><Box :size="15"/>Inventory</span><span><ReceiptText :size="15"/>Sales</span></div></section><section class="login-card"><span class="lock"><LockKeyhole :size="20"/></span><h2>Welcome back</h2><p>Sign in to Haseen Telecom admin.</p><form @submit.prevent="login"><FormField v-model="email" label="Email address" type="email" placeholder="you@company.com"/><label class="field"><span>Password</span><div class="password"><input v-model="password" :type="visible?'text':'password'" required placeholder="Enter your password"/><button type="button" @click="visible=!visible"><EyeOff v-if="visible" :size="18"/><Eye v-else :size="18"/></button></div></label><label class="remember"><input type="checkbox"/>Remember me</label><BaseButton type="submit"><span>{{loading?'Signing in…':'Sign in'}}</span><ArrowRight :size="18"/></BaseButton></form></section></main><footer>Haseen Telecom <i>·</i> Admin workspace</footer></div></template>
